INSERT INTO curriculum_nodes (id, slug, phase_id, order_index, title, subtitle, cs_foundation, ai_convergence, xp_reward, level_required, position_x, position_y, handbook_markdown, starter_code, test_suite, defense_prompts) VALUES
('node-5-41', 'phase-05-lesson-41-protocol-buffers-protobuf-v3-binary-encod', 'module-7', 41, 'Lesson 7.41: Protocol Buffers (Protobuf v3): Binary Encoding & Schema Evolution', 'Prerequisites: Phase 4 (Lesson 4.29)', 'Prerequisites: Phase 4 (Lesson 4.29) | Subtopics: 4 items', 'Systems project application', 200, 6, 1370.0, 2050.0, '# Lesson 5.41: Protocol Buffers (Protobuf v3): Binary Encoding & Schema Evolution

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 4 (Lesson 4.29)
- **Subtopics**:
  - `5.41.1` Protobuf binary encoding: Varints, Wire Types, ZigZag encoding for signed integers.
  - `5.41.2` The `.proto` interface definition: syntax, packages, message fields, field numbers (tags).
  - `5.41.3` Schema evolution rules: never change a field number, never delete a field tag (use `reserved`), handling unknown fields.
  - `5.41.4` Code generation: using `protoc` compiler to generate Python and TypeScript interfaces.
- **Key Failure Modes & Edge Cases**: Re-using previously deleted field numbers in `.proto` files, corrupting deserialization data in older service clients.
- **Verification & Mastery Check**: Inspect the raw binary byte stream of a serialized Protobuf message and decode field tags and varints manually.
- **Project Application**: AuthForge: gRPC service definitions.', '{"solution.py": "# Phase 5 // Lesson 5.41: Protocol Buffers (Protobuf v3): Binary Encoding & Schema Evolution\n\ndef solve():\n    \"\"\"\n    Verification: Inspect the raw binary byte stream of a serialized Protobuf message and decode field tags and varint\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.41", "subtopics_count": 4, "verification_criteria": "Inspect the raw binary byte stream of a serialized Protobuf message and decode field tags and varints manually.", "subtopics": ["5.41.1 Protobuf binary encoding: Varints, Wire Types, ZigZag encoding for signed integers.", "5.41.2 The `.proto` interface definition: syntax, packages, message fields, field numbers (tags).", "5.41.3 Schema evolution rules: never change a field number, never delete a field tag (use `reserved`), handling unknown fields.", "5.41.4 Code generation: using `protoc` compiler to generate Python and TypeScript interfaces."]}'::jsonb, '["Explain how this implementation prevents: Re-using previously deleted field numbers in `.proto` files, corrupting deserialization data in older service clients.", "How does Protocol Buffers (Protobuf v3): Binary Encoding & Schema Evolution scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-42', 'phase-05-lesson-42-grpc-services-streaming-deadline-propagat', 'module-7', 42, 'Lesson 7.42: gRPC Services, Streaming, & Deadline Propagation', 'Prerequisites: Lesson 5.41', 'Prerequisites: Lesson 5.41 | Subtopics: 4 items', 'Systems project application', 200, 6, 1250.0, 2100.0, '# Lesson 5.42: gRPC Services, Streaming, & Deadline Propagation

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.41
- **Subtopics**:
  - `5.42.1` gRPC service types: Unary RPC, Server Streaming, Client Streaming, Bidirectional Streaming.
  - `5.42.2` gRPC Interceptors: client and server middleware for auth, structured logging, and distributed tracing.
  - `5.42.3` Deadline Propagation: passing deadlines across distributed RPC chains (`grpc-timeout` header); failing fast on expired calls.
  - `5.42.4` gRPC Error Model: rich error details, status codes (`OK`, `UNAUTHENTICATED`, `DEADLINE_EXCEEDED`, `NOT_FOUND`).
- **Key Failure Modes & Edge Cases**: Omitting RPC call deadlines, allowing hung downstream microservices to tie up worker threads indefinitely.
- **Verification & Mastery Check**: Implement a unary and server-streaming gRPC service with client interceptors enforcing 500ms call deadlines.
- **Project Application**: AuthForge: Token validation service.', '{"solution.py": "# Phase 5 // Lesson 5.42: gRPC Services, Streaming, & Deadline Propagation\n\ndef solve():\n    \"\"\"\n    Verification: Implement a unary and server-streaming gRPC service with client interceptors enforcing 500ms call de\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.42", "subtopics_count": 4, "verification_criteria": "Implement a unary and server-streaming gRPC service with client interceptors enforcing 500ms call deadlines.", "subtopics": ["5.42.1 gRPC service types: Unary RPC, Server Streaming, Client Streaming, Bidirectional Streaming.", "5.42.2 gRPC Interceptors: client and server middleware for auth, structured logging, and distributed tracing.", "5.42.3 Deadline Propagation: passing deadlines across distributed RPC chains (`grpc-timeout` header); failing fast on expired calls.", "5.42.4 gRPC Error Model: rich error details, status codes (`OK`, `UNAUTHENTICATED`, `DEADLINE_EXCEEDED`, `NOT_FOUND`)."]}'::jsonb, '["Explain how this implementation prevents: Omitting RPC call deadlines, allowing hung downstream microservices to tie up worker threads indefinitely.", "How does gRPC Services, Streaming, & Deadline Propagation scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-43', 'phase-05-lesson-43-distributed-task-queues-producer-broker-w', 'module-7', 43, 'Lesson 7.43: Distributed Task Queues: Producer-Broker-Worker Architecture', 'Prerequisites: Phase 4 (Lesson 4.17)', 'Prerequisites: Phase 4 (Lesson 4.17) | Subtopics: 4 items', 'Systems project application', 200, 6, 1310.0, 2150.0, '# Lesson 5.43: Distributed Task Queues: Producer-Broker-Worker Architecture

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 4 (Lesson 4.17)
- **Subtopics**:
  - `5.43.1` Why background queues: decoupling slow operations (emails, PDF generation, webhooks) from HTTP request-response cycle.
  - `5.43.2` Architecture: Producers (FastAPI), Message Broker (Redis/RabbitMQ), Workers (Celery), Result Backend (Redis/PostgreSQL).
  - `5.43.3` Message serialization: JSON vs Pickle (security risks of Pickle deserialization exploits).
  - `5.43.4` Worker concurrency models: prefork (multi-process for CPU work), gevent/eventlet (green threads for I/O), solo.
- **Key Failure Modes & Edge Cases**: Using pickle serialization in message brokers, allowing remote code execution via forged task payloads.
- **Verification & Mastery Check**: Configure Celery with Redis broker and JSON serialization, dispatching tasks from a FastAPI endpoint.
- **Project Application**: TenantIQ: Asynchronous webhook ingestion.', '{"solution.py": "# Phase 5 // Lesson 5.43: Distributed Task Queues: Producer-Broker-Worker Architecture\n\ndef solve():\n    \"\"\"\n    Verification: Configure Celery with Redis broker and JSON serialization, dispatching tasks from a FastAPI endpoint\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.43", "subtopics_count": 4, "verification_criteria": "Configure Celery with Redis broker and JSON serialization, dispatching tasks from a FastAPI endpoint.", "subtopics": ["5.43.1 Why background queues: decoupling slow operations (emails, PDF generation, webhooks) from HTTP request-response cycle.", "5.43.2 Architecture: Producers (FastAPI), Message Broker (Redis/RabbitMQ), Workers (Celery), Result Backend (Redis/PostgreSQL).", "5.43.3 Message serialization: JSON vs Pickle (security risks of Pickle deserialization exploits).", "5.43.4 Worker concurrency models: prefork (multi-process for CPU work), gevent/eventlet (green threads for I/O), solo."]}'::jsonb, '["Explain how this implementation prevents: Using pickle serialization in message brokers, allowing remote code execution via forged task payloads.", "How does Distributed Task Queues: Producer-Broker-Worker Architecture scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-44', 'phase-05-lesson-44-task-idempotency-delivery-guarantees-ackn', 'module-7', 44, 'Lesson 7.44: Task Idempotency, Delivery Guarantees, & Acknowledgments', 'Prerequisites: Lesson 5.43', 'Prerequisites: Lesson 5.43 | Subtopics: 4 items', 'Systems project application', 200, 6, 1370.0, 2200.0, '# Lesson 5.44: Task Idempotency, Delivery Guarantees, & Acknowledgments

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.43
- **Subtopics**:
  - `5.44.1` Message delivery semantics: At-Least-Once delivery (default) vs At-Most-Once delivery.
  - `5.44.2` Why tasks MUST be idempotent: broker retries and network partitions will deliver tasks multiple times.
  - `5.44.3` Late Acknowledgments: `task_acks_late = True`; acknowledging tasks only after successful execution.
  - `5.44.4` Designing idempotent tasks: using database transactions, unique constraints, or Redis locks.
- **Key Failure Modes & Edge Cases**: Non-idempotent billing tasks charging a customer twice after a network timeout during worker task acknowledgment.
- **Verification & Mastery Check**: Implement an idempotent task that safely handles duplicate deliveries without duplicating state modifications.
- **Project Application**: TenantIQ: Metric calculation workers.', '{"solution.py": "# Phase 5 // Lesson 5.44: Task Idempotency, Delivery Guarantees, & Acknowledgments\n\ndef solve():\n    \"\"\"\n    Verification: Implement an idempotent task that safely handles duplicate deliveries without duplicating state modi\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.44", "subtopics_count": 4, "verification_criteria": "Implement an idempotent task that safely handles duplicate deliveries without duplicating state modifications.", "subtopics": ["5.44.1 Message delivery semantics: At-Least-Once delivery (default) vs At-Most-Once delivery.", "5.44.2 Why tasks MUST be idempotent: broker retries and network partitions will deliver tasks multiple times.", "5.44.3 Late Acknowledgments: `task_acks_late = True`; acknowledging tasks only after successful execution.", "5.44.4 Designing idempotent tasks: using database transactions, unique constraints, or Redis locks."]}'::jsonb, '["Explain how this implementation prevents: Non-idempotent billing tasks charging a customer twice after a network timeout during worker task acknowledgment.", "How does Task Idempotency, Delivery Guarantees, & Acknowledgments scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-45', 'phase-05-lesson-45-task-retries-exponential-backoff-dead-let', 'module-7', 45, 'Lesson 7.45: Task Retries, Exponential Backoff, & Dead-Letter Queues (DLQ)', 'Prerequisites: Lesson 5.44', 'Prerequisites: Lesson 5.44 | Subtopics: 4 items', 'Systems project application', 200, 6, 1250.0, 2250.0, '# Lesson 5.45: Task Retries, Exponential Backoff, & Dead-Letter Queues (DLQ)

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.44
- **Subtopics**:
  - `5.45.1` Handling transient failures: database deadlocks, third-party API rate limits.
  - `5.45.2` Exponential backoff with jitter: $T = 2^{	ext{retry}} + 	ext{random}(0, 1)$; preventing thundering herd on recovery.
  - `5.45.3` The Poison Pill problem: tasks that crash workers permanently on invalid inputs.
  - `5.45.4` Dead-Letter Queues (DLQ): routing permanently failed tasks to an error queue for human inspection.
- **Key Failure Modes & Edge Cases**: Retrying failed tasks immediately without backoff, flooding an already degraded external API and worsening outages.
- **Verification & Mastery Check**: Build a Celery task with exponential backoff and automatic routing to a dead-letter queue after 5 failed retries.
- **Project Application**: TenantIQ: GitHub webhook retry engine.', '{"solution.py": "# Phase 5 // Lesson 5.45: Task Retries, Exponential Backoff, & Dead-Letter Queues (DLQ)\n\ndef solve():\n    \"\"\"\n    Verification: Build a Celery task with exponential backoff and automatic routing to a dead-letter queue after 5 fa\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.45", "subtopics_count": 4, "verification_criteria": "Build a Celery task with exponential backoff and automatic routing to a dead-letter queue after 5 failed retries.", "subtopics": ["5.45.1 Handling transient failures: database deadlocks, third-party API rate limits.", "5.45.2 Exponential backoff with jitter: $T = 2^{\text{retry}} + \text{random}(0, 1)$; preventing thundering herd on recovery.", "5.45.3 The Poison Pill problem: tasks that crash workers permanently on invalid inputs.", "5.45.4 Dead-Letter Queues (DLQ): routing permanently failed tasks to an error queue for human inspection."]}'::jsonb, '["Explain how this implementation prevents: Retrying failed tasks immediately without backoff, flooding an already degraded external API and worsening outages.", "How does Task Retries, Exponential Backoff, & Dead-Letter Queues (DLQ) scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-6-1', 'phase-06-lesson-01-the-document-object-model-dom-tree-node-i', 'module-8', 1, 'Lesson 8.1: The Document Object Model (DOM) Tree & Node Interface', 'Prerequisites: Phase 0, Phase 1', 'Prerequisites: Phase 0, Phase 1 | Subtopics: 6 items', 'Systems project application', 220, 7, 1560.0, 50.0, '# Lesson 6.1: The Document Object Model (DOM) Tree & Node Interface

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 0, Phase 1
- **Subtopics**:
  - `6.1.1` HTML parsing tokenization and DOM tree construction algorithms
  - `6.1.2` Node interface hierarchy: Document, Element, CharacterData, and Text nodes
  - `6.1.3` Live NodeLists versus static NodeLists: querySelectorAll vs getElementsByTagName memory implications
  - `6.1.4` DOM mutation operations: DocumentFragment, createElement, appendChild, and batch tree insertions
  - `6.1.5` The Shadow DOM boundary: ShadowRoot, open vs closed encapsulation modes, and slot distribution
  - `6.1.6` DOM traversal performance: TreeWalker vs NodeIterator memory benchmarks
- **Key Failure Modes & Edge Cases**: Mutating live NodeLists inside for-loops causing infinite re-indexing; excessive reflows from incremental appendChild calls.
- **Verification & Mastery Check**: Implement an in-memory Virtual-to-Real DOM batch mounting engine using DocumentFragment; verify 10,000 node render under 16ms.
- **Project Application**: CompKit: Core DOM rendering abstraction layer.', '{"solution.py": "# Phase 6 // Lesson 6.1: The Document Object Model (DOM) Tree & Node Interface\n\ndef solve():\n    \"\"\"\n    Verification: Implement an in-memory Virtual-to-Real DOM batch mounting engine using DocumentFragment; verify 10,0\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "6.1", "subtopics_count": 6, "verification_criteria": "Implement an in-memory Virtual-to-Real DOM batch mounting engine using DocumentFragment; verify 10,000 node render under 16ms.", "subtopics": ["6.1.1 HTML parsing tokenization and DOM tree construction algorithms", "6.1.2 Node interface hierarchy: Document, Element, CharacterData, and Text nodes", "6.1.3 Live NodeLists versus static NodeLists: querySelectorAll vs getElementsByTagName memory implications", "6.1.4 DOM mutation operations: DocumentFragment, createElement, appendChild, and batch tree insertions", "6.1.5 The Shadow DOM boundary: ShadowRoot, open vs closed encapsulation modes, and slot distribution", "6.1.6 DOM traversal performance: TreeWalker vs NodeIterator memory benchmarks"]}'::jsonb, '["Explain how this implementation prevents: Mutating live NodeLists inside for-loops causing infinite re-indexing; excessive reflows from incremental appendChild ca", "How does The Document Object Model (DOM) Tree & Node Interface scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-6-2', 'phase-06-lesson-02-browser-event-dispatch-loop-event-archite', 'module-8', 2, 'Lesson 8.2: Browser Event Dispatch Loop & Event Architecture', 'Prerequisites: Lesson 6.1', 'Prerequisites: Lesson 6.1 | Subtopics: 6 items', 'Systems project application', 220, 7, 1620.0, 100.0, '# Lesson 6.2: Browser Event Dispatch Loop & Event Architecture

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 6.1
- **Subtopics**:
  - `6.2.1` Event flow phases: capturing phase, target phase, and bubbling phase
  - `6.2.2` Synthetic vs native Event objects: bubbles, cancelable, composed, and defaultPrevented properties
  - `6.2.3` Event delegation patterns: handling dynamic children with matching selectors and memory minimization
  - `6.2.4` Event cancellation semantics: stopPropagation vs stopImmediatePropagation vs preventDefault
  - `6.2.5` Passive event listeners: optimizing touch and wheel scroll performance by unblocking compositor threads
  - `6.2.6` CustomEvent dispatching and inter-component decoupled bus architectures
- **Key Failure Modes & Edge Cases**: Calling stopPropagation breaking analytics tracking scripts; scroll jank caused by non-passive touchmove listeners.
- **Verification & Mastery Check**: Write an event delegation manager handling nested dynamic elements with capture-phase boundary interceptors.
- **Project Application**: CompKit: Headless accessible interactive component dispatchers.', '{"solution.py": "# Phase 6 // Lesson 6.2: Browser Event Dispatch Loop & Event Architecture\n\ndef solve():\n    \"\"\"\n    Verification: Write an event delegation manager handling nested dynamic elements with capture-phase boundary inter\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "6.2", "subtopics_count": 6, "verification_criteria": "Write an event delegation manager handling nested dynamic elements with capture-phase boundary interceptors.", "subtopics": ["6.2.1 Event flow phases: capturing phase, target phase, and bubbling phase", "6.2.2 Synthetic vs native Event objects: bubbles, cancelable, composed, and defaultPrevented properties", "6.2.3 Event delegation patterns: handling dynamic children with matching selectors and memory minimization", "6.2.4 Event cancellation semantics: stopPropagation vs stopImmediatePropagation vs preventDefault", "6.2.5 Passive event listeners: optimizing touch and wheel scroll performance by unblocking compositor threads", "6.2.6 CustomEvent dispatching and inter-component decoupled bus architectures"]}'::jsonb, '["Explain how this implementation prevents: Calling stopPropagation breaking analytics tracking scripts; scroll jank caused by non-passive touchmove listeners.", "How does Browser Event Dispatch Loop & Event Architecture scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-6-3', 'phase-06-lesson-03-html5-semantic-architecture-structured-do', 'module-8', 3, 'Lesson 8.3: HTML5 Semantic Architecture & Structured Document Outlines', 'Prerequisites: Lesson 6.1', 'Prerequisites: Lesson 6.1 | Subtopics: 6 items', 'Systems project application', 220, 7, 1500.0, 150.0, '# Lesson 6.3: HTML5 Semantic Architecture & Structured Document Outlines

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 6.1
- **Subtopics**:
  - `6.3.1` Semantic elements vs generic containers: header, nav, main, article, section, aside, footer
  - `6.3.2` Heading levels (h1-h6) and document outline algorithms in modern search and accessibility engines
  - `6.3.3` HTML forms specification: form controls, formnovalidate, enctype, autocomplete attributes, and fieldsets
  - `6.3.4` Embedded media elements: picture element with art direction media queries and source srcset fallbacks
  - `6.3.5` Dialog element lifecycle: show(), showModal(), top-layer positioning, and backdrop pseudo-elements
  - `6.3.6` Microdata and JSON-LD schema integration for rich machine-readable metadata
- **Key Failure Modes & Edge Cases**: Using multiple h1 elements haphazardly destroying accessibility tree outlines; unclosed modal dialogs trapping focus.
- **Verification & Mastery Check**: Build a zero-JS accessible modal dialog and form submission pipeline validating native constraint validation API.
- **Project Application**: TenantIQ: Public onboarding landing pages and registration forms.', '{"solution.py": "# Phase 6 // Lesson 6.3: HTML5 Semantic Architecture & Structured Document Outlines\n\ndef solve():\n    \"\"\"\n    Verification: Build a zero-JS accessible modal dialog and form submission pipeline validating native constraint va\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "6.3", "subtopics_count": 6, "verification_criteria": "Build a zero-JS accessible modal dialog and form submission pipeline validating native constraint validation API.", "subtopics": ["6.3.1 Semantic elements vs generic containers: header, nav, main, article, section, aside, footer", "6.3.2 Heading levels (h1-h6) and document outline algorithms in modern search and accessibility engines", "6.3.3 HTML forms specification: form controls, formnovalidate, enctype, autocomplete attributes, and fieldsets", "6.3.4 Embedded media elements: picture element with art direction media queries and source srcset fallbacks", "6.3.5 Dialog element lifecycle: show(), showModal(), top-layer positioning, and backdrop pseudo-elements", "6.3.6 Microdata and JSON-LD schema integration for rich machine-readable metadata"]}'::jsonb, '["Explain how this implementation prevents: Using multiple h1 elements haphazardly destroying accessibility tree outlines; unclosed modal dialogs trapping focus.", "How does HTML5 Semantic Architecture & Structured Document Outlines scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-6-4', 'phase-06-lesson-04-web-accessibility-a11y-wcag-2-2-aaa-the-a', 'module-8', 4, 'Lesson 8.4: Web Accessibility (a11y), WCAG 2.2 AAA & The Accessibility Tree', 'Prerequisites: Lesson 6.2, Lesson 6.3', 'Prerequisites: Lesson 6.2, Lesson 6.3 | Subtopics: 6 items', 'Systems project application', 220, 7, 1560.0, 200.0, '# Lesson 6.4: Web Accessibility (a11y), WCAG 2.2 AAA & The Accessibility Tree

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 6.2, Lesson 6.3
- **Subtopics**:
  - `6.4.1` How browsers transform the DOM tree into the platform-specific Accessibility Tree (AOM)
  - `6.4.2` ARIA roles, states, and properties: role landmark usage, aria-expanded, aria-controls, aria-live regions
  - `6.4.3` Keyboard accessibility: tabindex rules (0 vs -1 vs positive integers), keyboard focus traps, and roaming tabindex
  - `6.4.4` Color contrast ratios: WCAG 2.2 AA (4.5:1) vs AAA (7:1) mathematical luminance formulas
  - `6.4.5` Screen reader interaction paradigms: NVDA, VoiceOver rotor navigation, and virtual cursor modes
  - `6.4.6` Automated auditing integration with axe-core and Pa11y in CI/CD test suites
- **Key Failure Modes & Edge Cases**: Overusing ARIA attributes (first rule of ARIA: don''t use ARIA if native HTML exists); broken keyboard focus traps.
- **Verification & Mastery Check**: Audit and refactor an inaccessible combobox component to pass WCAG 2.2 AAA compliance with full keyboard navigation.
- **Project Application**: CompKit: Fully accessible headless combobox and modal components.', '{"solution.py": "# Phase 6 // Lesson 6.4: Web Accessibility (a11y), WCAG 2.2 AAA & The Accessibility Tree\n\ndef solve():\n    \"\"\"\n    Verification: Audit and refactor an inaccessible combobox component to pass WCAG 2.2 AAA compliance with full keyb\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "6.4", "subtopics_count": 6, "verification_criteria": "Audit and refactor an inaccessible combobox component to pass WCAG 2.2 AAA compliance with full keyboard navigation.", "subtopics": ["6.4.1 How browsers transform the DOM tree into the platform-specific Accessibility Tree (AOM)", "6.4.2 ARIA roles, states, and properties: role landmark usage, aria-expanded, aria-controls, aria-live regions", "6.4.3 Keyboard accessibility: tabindex rules (0 vs -1 vs positive integers), keyboard focus traps, and roaming tabindex", "6.4.4 Color contrast ratios: WCAG 2.2 AA (4.5:1) vs AAA (7:1) mathematical luminance formulas", "6.4.5 Screen reader interaction paradigms: NVDA, VoiceOver rotor navigation, and virtual cursor modes", "6.4.6 Automated auditing integration with axe-core and Pa11y in CI/CD test suites"]}'::jsonb, '["Explain how this implementation prevents: Overusing ARIA attributes (first rule of ARIA: don''t use ARIA if native HTML exists); broken keyboard focus traps.", "How does Web Accessibility (a11y), WCAG 2.2 AAA & The Accessibility Tree scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-6-5', 'phase-06-lesson-05-browser-storage-systems-quotas-eviction-p', 'module-8', 5, 'Lesson 8.5: Browser Storage Systems, Quotas & Eviction Policies', 'Prerequisites: Phase 0, Lesson 6.1', 'Prerequisites: Phase 0, Lesson 6.1 | Subtopics: 6 items', 'Systems project application', 220, 7, 1620.0, 250.0, '# Lesson 6.5: Browser Storage Systems, Quotas & Eviction Policies

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 0, Lesson 6.1
- **Subtopics**:
  - `6.5.1` Storage comparison: Cookies, Web Storage (localStorage/sessionStorage), IndexedDB, and Cache API
  - `6.5.2` Storage quotas and eviction priorities: best-effort vs persistent storage requests (navigator.storage.persist)
  - `6.5.3` IndexedDB architecture: Object stores, primary keys, key paths, auto-increment, and index cursors
  - `6.5.4` IndexedDB transaction lifecycles: readonly vs readwrite, auto-commit behavior, and error handling
  - `6.5.5` Client-side database versioning and onupgradeneeded schema migration pipelines
  - `6.5.6` Storage security: Same-Origin Policy enforcement, path isolation, and encryption of sensitive tokens at rest
- **Key Failure Modes & Edge Cases**: Blocking main thread with synchronous localStorage reads of multi-megabyte JSON; unhandled IndexedDB VersionError.
- **Verification & Mastery Check**: Build a robust IndexedDB wrapper supporting promise-based transactions, secondary indexing, and automatic migrations.
- **Project Application**: TenantIQ: Client-side offline cache for multi-tenant draft documents.', '{"solution.py": "# Phase 6 // Lesson 6.5: Browser Storage Systems, Quotas & Eviction Policies\n\ndef solve():\n    \"\"\"\n    Verification: Build a robust IndexedDB wrapper supporting promise-based transactions, secondary indexing, and auto\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "6.5", "subtopics_count": 6, "verification_criteria": "Build a robust IndexedDB wrapper supporting promise-based transactions, secondary indexing, and automatic migrations.", "subtopics": ["6.5.1 Storage comparison: Cookies, Web Storage (localStorage/sessionStorage), IndexedDB, and Cache API", "6.5.2 Storage quotas and eviction priorities: best-effort vs persistent storage requests (navigator.storage.persist)", "6.5.3 IndexedDB architecture: Object stores, primary keys, key paths, auto-increment, and index cursors", "6.5.4 IndexedDB transaction lifecycles: readonly vs readwrite, auto-commit behavior, and error handling", "6.5.5 Client-side database versioning and onupgradeneeded schema migration pipelines", "6.5.6 Storage security: Same-Origin Policy enforcement, path isolation, and encryption of sensitive tokens at rest"]}'::jsonb, '["Explain how this implementation prevents: Blocking main thread with synchronous localStorage reads of multi-megabyte JSON; unhandled IndexedDB VersionError.", "How does Browser Storage Systems, Quotas & Eviction Policies scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb)
